"""Cartoon sounds for the engine's events, made by synthesis (nothing downloaded, nothing generated by a model).
usage: python devtools/make_sfx.py      -> engine/sounds/<name>.wav (mono, 44.1 kHz, 16 bit)

They are placeholders in the style of a puppet show: short, soft, wooden. Any of them may be replaced by a real
recording of the same name; the engine (engine/sound.gd) does not care where a file came from.
  step   a soft wooden tap (a puppet's foot)            land   a thud, lower and longer
  jump   a quick rising "whoop"                         clap   a short bright burst
  hit    a punchy thump with a slap on top              whoosh a swell of air (a swing, a throw)
  pop    a small cork pop (a thing picked up, put down) spin   a fast whirr (a spin, a twirl)
INSTRUMENTS the heroes play (engine/sound.gd "beats"), all in C major over the chords C G Am F, so that heroes
playing at once play together:
  guitar_<chord>      a strum down the six strings (plucked-string synthesis)
  balalaika_<chord>   three bright strings, short
  bass_<chord>_1, _2  a double bass plucked: the root, the fifth
  accordion_<chord>   reeds, two voices a little apart (musette), a chord over a bass note
  pipe_<chord>_1.._3  a wooden pipe: three notes of the chord, breathy
  drum_1, drum_2      a marching drum, the two sticks
"""
from pathlib import Path

import numpy as np
from scipy.io import wavfile
from scipy.signal import lfilter

ROOT = Path(__file__).resolve().parent.parent
SR = 44100
rng = np.random.default_rng(7)          # (the same files every time)


def t(sec):
    return np.arange(int(SR * sec)) / SR


def env(x, attack, decay):
    """An envelope: up in `attack` s, then down exponentially with time constant `decay` s."""
    tt = np.arange(len(x)) / SR
    a = np.clip(tt / max(attack, 1e-4), 0, 1)
    return x * a * np.exp(-np.maximum(tt - attack, 0) / decay)


def lowpass(x, cutoff):
    """One-pole low-pass, run twice (soft)."""
    k = np.exp(-2 * np.pi * cutoff / SR)
    for _ in range(2):
        y = np.empty_like(x)
        acc = 0.0
        for i, v in enumerate(x):
            acc = (1 - k) * v + k * acc
            y[i] = acc
        x = y
    return x


def highpass(x, cutoff):
    return x - lowpass(x, cutoff)


def tone(f0, f1, sec):
    """A sine gliding from f0 to f1 Hz."""
    tt = t(sec)
    f = np.geomspace(f0, f1, len(tt))
    return np.sin(2 * np.pi * np.cumsum(f) / SR)


def noise(sec):
    return rng.standard_normal(int(SR * sec))


def save(name, x, gain=0.8):
    x = x / max(np.max(np.abs(x)), 1e-6) * gain
    fade = int(0.004 * SR)
    x[-fade:] *= np.linspace(1, 0, fade)
    out = ROOT / "engine" / "sounds" / f"{name}.wav"
    out.parent.mkdir(parents=True, exist_ok=True)
    wavfile.write(out, SR, (x * 32767).astype(np.int16))
    print(out, f"{len(x) / SR:.2f} s")


def main():
    # step: a wooden knock - a damped 180 Hz body and a click of filtered noise
    body = env(tone(190, 150, 0.12), 0.002, 0.025)
    click = env(highpass(noise(0.12), 1500), 0.0005, 0.006)
    save("step", body + 0.35 * click, 0.5)
    # land: lower, longer, with a little rattle
    body = env(tone(120, 70, 0.35), 0.003, 0.07)
    thud = env(lowpass(noise(0.35), 400), 0.002, 0.05)
    save("land", body + 0.8 * thud, 0.8)
    # jump: a rising whoop
    w = env(tone(260, 700, 0.22), 0.01, 0.09) + 0.15 * env(tone(520, 1400, 0.22), 0.01, 0.06)
    save("jump", w, 0.55)
    # clap: a band of noise, very short, two reflections
    c = env(highpass(lowpass(noise(0.2), 6000), 900), 0.0008, 0.018)
    c[int(0.012 * SR):] += 0.35 * c[:len(c) - int(0.012 * SR)]
    save("clap", c, 0.85)
    # hit: a punchy low thump and a slap
    body = env(tone(140, 60, 0.3), 0.001, 0.06)
    slap = env(highpass(noise(0.3), 1200), 0.0005, 0.02)
    save("hit", body + 0.6 * slap, 0.9)
    # whoosh: noise swelling and falling, its colour moving up
    n = noise(0.45)
    lo, hi = lowpass(n, 700), lowpass(n, 2500)
    m = np.linspace(0, 1, len(n))
    sw = (lo * (1 - m) + hi * m) * np.sin(np.pi * np.linspace(0, 1, len(n))) ** 2
    save("whoosh", sw, 0.5)
    # pop: a cork
    p = env(tone(900, 300, 0.08), 0.0005, 0.012) + 0.4 * env(highpass(noise(0.08), 2000), 0.0003, 0.004)
    save("pop", p, 0.6)
    # spin: a whirr - noise beating at 18 Hz, rising
    n = lowpass(noise(0.8), 1800)
    rate = np.geomspace(10, 22, len(n))
    beat = 0.5 + 0.5 * np.sin(2 * np.pi * np.cumsum(rate) / SR)
    save("spin", n * beat * np.sin(np.pi * np.linspace(0, 1, len(n))), 0.45)
    music_box()
    instruments()


def lp(x, cutoff):
    """One-pole low-pass, run twice (fast)."""
    k = np.exp(-2 * np.pi * cutoff / SR)
    for _ in range(2):
        x = lfilter([1 - k], [1, -k], x)
    return x


def pluck(f, sec, decay=0.996, bright=0.5):
    """A plucked string (Karplus-Strong): a burst of noise going round a loop as long as one wave, softened each time."""
    n = int(SR * sec)
    period = SR / f
    p = int(period)
    frac = period - p
    buf = lp(rng.uniform(-1, 1, p + 2), 1500 + 6000 * bright)
    out = np.zeros(n)
    out[:len(buf)] = buf[:n]
    # y[i] = decay * (avg of the two samples one period back, with the fraction of a sample for the right pitch)
    for i in range(p + 2, n):
        a = out[i - p]
        b = out[i - p - 1]
        out[i] = decay * ((1 - frac) * (0.5 * a + 0.5 * b) + frac * (0.5 * b + 0.5 * out[i - p - 2]))
    return out


def strum(freqs, sec, gap, decay, bright, fade):
    out = np.zeros(int(SR * (sec + gap * len(freqs))))
    for i, f in enumerate(freqs):
        s0 = int(i * gap * SR)
        x = pluck(f, sec, decay, bright)
        out[s0:s0 + len(x)] += x * (1.0 - 0.06 * i)
    tt = np.arange(len(out)) / SR
    return out * np.exp(-tt / fade)


def note(name):
    names = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}
    return 440.0 * 2 ** ((names[name[0]] + 12 * (int(name[1:]) - 4) - 9) / 12)


def instruments():
    guitar = {"C": "C3 E3 G3 C4 E4", "G": "G2 B2 D3 G3 B3 G4", "Am": "A2 E3 A3 C4 E4", "F": "F2 C3 F3 A3 C4 F4"}
    for ch, ns in guitar.items():
        x = strum([note(n) for n in ns.split()], 1.6, 0.014, 0.997, 0.55, 0.9)
        save(f"guitar_{ch}", lp(x, 5000), 0.55)
    bala = {"C": "G4 C5 E5", "G": "G4 B4 D5", "Am": "A4 C5 E5", "F": "A4 C5 F5"}
    for ch, ns in bala.items():
        x = strum([note(n) for n in ns.split()], 0.7, 0.008, 0.993, 0.9, 0.28)
        save(f"balalaika_{ch}", x, 0.5)
    bass = {"C": ["C2", "G2"], "G": ["G1", "D2"], "Am": ["A1", "E2"], "F": ["F1", "C2"]}
    for ch, ns in bass.items():
        for k, n in enumerate(ns):
            f = note(n)
            tt = t(1.3)
            x = lp(pluck(f * 2, 1.3, 0.996, 0.15), 700) + 0.8 * np.sin(2 * np.pi * f * tt) * np.exp(-tt / 0.45)
            x *= np.clip(tt / 0.004, 0, 1) * np.exp(-tt / 0.6)
            save(f"bass_{ch}_{k + 1}", x, 0.75)
    acc = {"C": ("C3", "C4 E4 G4"), "G": ("G2", "B3 D4 G4"), "Am": ("A2", "A3 C4 E4"), "F": ("F2", "A3 C4 F4")}
    for ch, (b, ns) in acc.items():
        tt = t(1.0)
        x = np.zeros(len(tt))
        for n in [b] + ns.split():
            f = note(n)
            for det in (-0.006, 0.006):              # two reeds a little apart: the accordion's wobble
                ph = 2 * np.pi * f * (1 + det) * tt
                x += (2 * (ph / (2 * np.pi) % 1.0) - 1) * (1.2 if n == b else 1.0)   # a reed: a saw
        x = lp(x, 2600)
        shape = np.clip(tt / 0.05, 0, 1) * np.clip((1.0 - tt) / 0.18, 0, 1)
        save(f"accordion_{ch}", x * shape, 0.45)
    pipe = {"C": "E5 G5 C6", "G": "D5 G5 B5", "Am": "E5 A5 C6", "F": "F5 A5 C6"}
    for ch, ns in pipe.items():
        for k, n in enumerate(ns.split()):
            f = note(n)
            tt = t(0.5)
            vib = 1 + 0.004 * np.sin(2 * np.pi * 5.5 * tt) * np.clip(tt / 0.2, 0, 1)
            ph = 2 * np.pi * np.cumsum(f * vib) / SR
            x = np.sin(ph) + 0.18 * np.sin(2 * ph) + 0.06 * np.sin(3 * ph)
            breath = lp(highpass(noise(0.5), 1500), 5000) * 0.05
            shape = np.clip(tt / 0.035, 0, 1) * np.clip((0.5 - tt) / 0.12, 0, 1)
            save(f"pipe_{ch}_{k + 1}", (x + breath) * shape, 0.45)
    for k, (f0, gain) in enumerate([(200, 0.8), (180, 0.7)]):
        body = env(tone(f0, f0 * 0.7, 0.35), 0.001, 0.05)
        snare = env(lp(highpass(noise(0.35), 1800), 7000), 0.0005, 0.09)
        save(f"drum_{k + 1}", body + 0.55 * snare, gain)


def music_box():
    """A placeholder tune: a music box playing a slow pentatonic melody over a soft drone, 12.8 s, loops cleanly."""
    beat = 0.4
    notes = [0, 4, 7, 9, 7, 4, 2, 4, 0, 2, 4, 7, 4, 2, 0, -3,
             0, 4, 7, 12, 9, 7, 4, 2, 4, 7, 9, 7, 4, 2, 0, 0]
    total = int(SR * beat * len(notes))
    out = np.zeros(total + 2 * SR)
    for i, n in enumerate(notes):
        f = 523.25 * 2 ** (n / 12)
        tt = t(1.6)
        bell = (np.sin(2 * np.pi * f * tt) + 0.35 * np.sin(2 * np.pi * 2.76 * f * tt) * np.exp(-tt / 0.15)
                + 0.2 * np.sin(2 * np.pi * 5.4 * f * tt) * np.exp(-tt / 0.05))
        bell *= np.exp(-tt / 0.5) * np.clip(tt / 0.003, 0, 1)
        s0 = int(i * beat * SR)
        out[s0:s0 + len(bell)] += bell * (0.9 if i % 4 == 0 else 0.7)
    # what rings past the end comes in again at the start: the loop has no seam
    out[:2 * SR] += out[total:total + 2 * SR]
    out = out[:total]
    tt = np.arange(total) / SR
    drone = 0.12 * (np.sin(2 * np.pi * 130.8 * tt) + 0.5 * np.sin(2 * np.pi * 196.0 * tt))
    save("music_box", out + drone, 0.6)


if __name__ == "__main__":
    main()
